import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { sendChatMessage, fetchChatSessions, streamChatMessage } from '../redux/slices/chatSlice';
import './TherapyChat.css';

const TherapyChat = () => {
  const dispatch = useDispatch();
  const messagesEndRef = useRef(null);
  
  // Get data from Redux store
  const { 
    isLoading, 
    error: reduxError, 
    currentSession, 
    isStreaming, 
    currentStreamedMessage 
  } = useSelector(state => state.chat);
  
  const [messages, setMessages] = useState([
    { role: 'assistant', content: "Hello! I'm your mindfulness therapy assistant. How are you feeling today?" }
  ]);
  const [newMessage, setNewMessage] = useState('');
  const [error, setError] = useState(null);

  // Scroll to bottom of messages
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Effect to scroll to bottom when messages change or when streaming progress
  useEffect(() => {
    scrollToBottom();
  }, [messages, currentStreamedMessage]);

  // Effect to fetch chat sessions when component mounts
  useEffect(() => {
    dispatch(fetchChatSessions());
  }, [dispatch]);

  // Effect to update error from Redux
  useEffect(() => {
    if (reduxError) {
      setError(reduxError);
    }
  }, [reduxError]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    
    if (!newMessage.trim()) return;
    
    // Add user message to UI immediately
    const userMessage = { role: 'user', content: newMessage };
    const updatedMessages = [...messages, userMessage];
    setMessages(updatedMessages);
    setNewMessage('');
    setError(null);
    
    try {
      // Dispatch the streaming action
      await dispatch(
        streamChatMessage({
          message: newMessage,
          chatSessionId: currentSession
        })
      );
      
      // The streamed response will be handled by the Redux slice
      // and displayed through the currentStreamedMessage state
    } catch (err) {
      console.error('Error sending message:', err);
      setError('Failed to get a response. Please try again.');
    }
  };

  return (
    <div className="therapy-chat-page">
      <div className="container">
        <div className="chat-container">
          <div className="chat-header">
            <h1>Therapy Chat</h1>
            {error && <div className="error-banner">{error}</div>}
          </div>
          
          <div className="chat-messages">
            {messages.map((message, index) => (
              <div key={index} className={`message message-${message.role}`}>
                {message.content}
              </div>
            ))}
            
            {/* Display streaming message in real-time */}
            {isStreaming && currentStreamedMessage && (
              <div className="message message-assistant streaming">
                {currentStreamedMessage}
                <span className="cursor"></span>
              </div>
            )}
            
            {isLoading && !isStreaming && (
              <div className="message message-assistant loading">
                <div className="loading-dots">
                  <span></span>
                  <span></span>
                  <span></span>
                </div>
              </div>
            )}
            
            {/* Empty div for scrolling to bottom */}
            <div ref={messagesEndRef} />
          </div>
          
          <form className="chat-input-form" onSubmit={handleSendMessage}>
            <input
              type="text"
              placeholder="Type your message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              disabled={isLoading || isStreaming}
              autoFocus
            />
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={isLoading || isStreaming || !newMessage.trim()}
            >
              Send
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default TherapyChat;
